-- RRC204 exact existing-ID entry correction; explicit guarded rollback only; never automatically execute.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE changed_rows INT DEFAULT 0;
 DECLARE step_rows INT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC204 fresh transaction-free session required'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC204 strict mode required'; END IF;
 IF DATABASE()<>'peq_housing_test' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC204 target database mismatch'; END IF;
 IF (SELECT COUNT(*)FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME IN('items','tradeskill_recipe','tradeskill_recipe_entries')AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC204 InnoDB foundation mismatch'; END IF;
 IF (SELECT COUNT(*)FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME='tradeskill_recipe')<>16 OR(SELECT COUNT(*)FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC204 schema mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc204_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc204_before LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc204_after LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc204_added LIKE tradeskill_recipe_entries;
